[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>MedBook — Find and Book Top Doctors Instantly</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    :root {
      --primary: #1B1464;
      --accent: #FFD930;
      --white: #FFFFFF;
      --light-gray: #F5F7FA;
      --text-dark: #1A1A2E;
      --text-muted: #6B7280;
      --border: #E5E7EB;
      --success: #10B981;
      --radius: 12px;
      --radius-sm: 8px;
      --shadow: 0 4px 24px rgba(27, 20, 100, 0.08);
      --shadow-lg: 0 8px 40px rgba(27, 20, 100, 0.12);
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
      color: var(--text-dark);
      background: var(--white);
      line-height: 1.6;
      overflow-x: hidden;
    }

    a {
      text-decoration: none;
      color: inherit;
    }

    /* Header */
    .header {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      background: var(--white);
      border-bottom: 1px solid var(--border);
      z-index: 1000;
      height: 72px;
    }

    .header-inner {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .logo {
      font-size: 24px;
      font-weight: 800;
      color: var(--primary);
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .logo-icon {
      width: 36px;
      height: 36px;
      background: var(--primary);
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .logo-icon svg {
      width: 22px;
      height: 22px;
      fill: var(--white);
    }

    .nav-desktop {
      display: flex;
      align-items: center;
      gap: 32px;
    }

    .nav-links {
      display: flex;
      align-items: center;
      gap: 32px;
      list-style: none;
    }

    .nav-links a {
      font-weight: 500;
      font-size: 15px;
      color: var(--text-dark);
      transition: color 0.2s;
    }

    .nav-links a:hover {
      color: var(--primary);
    }

    .nav-buttons {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      padding: 10px 20px;
      border-radius: var(--radius-sm);
      font-weight: 600;
      font-size: 14px;
      cursor: pointer;
      transition: all 0.2s;
      border: none;
    }

    .btn-ghost {
      background: transparent;
      color: var(--text-dark);
    }

    .btn-ghost:hover {
      background: var(--light-gray);
    }

    .btn-primary {
      background: var(--primary);
      color: var(--white);
    }

    .btn-primary:hover {
      background: #15124f;
      transform: translateY(-1px);
    }

    .btn-accent {
      background: var(--accent);
      color: var(--primary);
    }

    .btn-accent:hover {
      background: #e6c42b;
    }

    .hamburger {
      display: none;
      flex-direction: column;
      gap: 5px;
      cursor: pointer;
      padding: 8px;
      background: none;
      border: none;
    }

    .hamburger span {
      width: 24px;
      height: 2px;
      background: var(--text-dark);
      border-radius: 2px;
      transition: all 0.3s;
    }

    /* Mobile Menu */
    .mobile-menu {
      display: none;
      position: fixed;
      top: 0;
      right: -100%;
      width: 300px;
      height: 100vh;
      background: var(--white);
      box-shadow: var(--shadow-lg);
      z-index: 2000;
      transition: right 0.3s ease;
      padding: 24px;
    }

    .mobile-menu.active {
      right: 0;
    }

    .mobile-menu-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 32px;
    }

    .mobile-menu-close {
      background: none;
      border: none;
      cursor: pointer;
      padding: 8px;
    }

    .mobile-nav-links {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 8px;
    }

    .mobile-nav-links a {
      display: block;
      padding: 12px 16px;
      font-weight: 500;
      border-radius: var(--radius-sm);
      transition: background 0.2s;
    }

    .mobile-nav-links a:hover {
      background: var(--light-gray);
    }

    .mobile-menu-overlay {
      display: none;
      position: fixed;
      inset: 0;
      background: rgba(0,0,0,0.5);
      z-index: 1500;
      opacity: 0;
      transition: opacity 0.3s;
    }

    .mobile-menu-overlay.active {
      opacity: 1;
    }

    /* Hero Section */
    .hero {
      padding: 140px 24px 80px;
      background: linear-gradient(180deg, var(--light-gray) 0%, var(--white) 100%);
      text-align: center;
    }

    .hero-title {
      font-size: clamp(36px, 6vw, 56px);
      font-weight: 800;
      color: var(--primary);
      margin-bottom: 20px;
      line-height: 1.15;
    }

    .hero-subtitle {
      font-size: 18px;
      color: var(--text-muted);
      max-width: 640px;
      margin: 0 auto 40px;
    }

    /* Search Bar */
    .search-container {
      max-width: 900px;
      margin: 0 auto;
    }

    .search-bar {
      background: var(--white);
      border-radius: var(--radius);
      box-shadow: var(--shadow-lg);
      padding: 8px;
      display: flex;
      gap: 4px;
    }

    .search-field {
      flex: 1;
      position: relative;
    }

    .search-field input,
    .search-field select {
      width: 100%;
      padding: 16px 16px 16px 48px;
      border: 2px solid transparent;
      border-radius: var(--radius-sm);
      font-size: 16px;
      font-family: inherit;
      background: var(--light-gray);
      transition: all 0.2s;
      outline: none;
    }

    .search-field input:focus,
    .search-field select:focus {
      border-color: var(--primary);
      background: var(--white);
    }

    .search-field .field-icon {
      position: absolute;
      left: 16px;
      top: 50%;
      transform: translateY(-50%);
      color: var(--text-muted);
    }

    .search-btn {
      padding: 16px 32px;
      background: var(--primary);
      color: var(--white);
      border: none;
      border-radius: var(--radius-sm);
      font-weight: 600;
      font-size: 16px;
      cursor: pointer;
      transition: all 0.2s;
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .search-btn:hover {
      background: #15124f;
      transform: translateY(-1px);
    }

    /* Autocomplete */
    .autocomplete {
      position: absolute;
      top: calc(100% + 4px);
      left: 0;
      right: 0;
      background: var(--white);
      border-radius: var(--radius-sm);
      box-shadow: var(--shadow-lg);
      border: 1px solid var(--border);
      max-height: 300px;
      overflow-y: auto;
      display: none;
      z-index: 100;
    }

    .autocomplete.active {
      display: block;
    }

    .autocomplete-item {
      padding: 12px 16px;
      cursor: pointer;
      display: flex;
      align-items: center;
      gap: 12px;
      transition: background 0.15s;
    }

    .autocomplete-item:hover {
      background: var(--light-gray);
    }

    .autocomplete-item-icon {
      width: 32px;
      height: 32px;
      background: var(--light-gray);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--primary);
    }

    .autocomplete-item-text {
      flex: 1;
    }

    .autocomplete-item-text strong {
      display: block;
      font-weight: 600;
    }

    .autocomplete-item-text span {
      font-size: 13px;
      color: var(--text-muted);
    }

    /* Specialties Section */
    .specialties {
      padding: 80px 24px;
      max-width: 1200px;
      margin: 0 auto;
    }

    .section-header {
      text-align: center;
      margin-bottom: 48px;
    }

    .section-title {
      font-size: 32px;
      font-weight: 700;
      color: var(--primary);
      margin-bottom: 12px;
    }

    .section-subtitle {
      font-size: 16px;
      color: var(--text-muted);
    }

    .specialties-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
      gap: 20px;
    }

    .specialty-card {
      background: var(--white);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      padding: 28px 20px;
      text-align: center;
      cursor: pointer;
      transition: all 0.25s;
    }

    .specialty-card:hover {
      border-color: var(--primary);
      box-shadow: var(--shadow);
      transform: translateY(-4px);
    }

    .specialty-icon {
      width: 64px;
      height: 64px;
      margin: 0 auto 16px;
      background: var(--light-gray);
      border-radius: var(--radius);
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--primary);
      transition: all 0.25s;
    }

    .specialty-card:hover .specialty-icon {
      background: var(--primary);
      color: var(--white);
    }

    .specialty-card h3 {
      font-size: 16px;
      font-weight: 600;
      margin-bottom: 6px;
    }

    .specialty-card p {
      font-size: 13px;
      color: var(--text-muted);
    }

    /* Stats Section */
    .stats {
      background: var(--primary);
      padding: 48px 24px;
    }

    .stats-inner {
      max-width: 1200px;
      margin: 0 auto;
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 32px;
    }

    .stat-item {
      text-align: center;
      color: var(--white);
    }

    .stat-value {
      font-size: 36px;
      font-weight: 800;
      margin-bottom: 4px;
    }

    .stat-value span {
      color: var(--accent);
    }

    .stat-label {
      font-size: 14px;
      opacity: 0.85;
    }

    /* How It Works */
    .how-it-works {
      padding: 80px 24px;
      background: var(--light-gray);
    }

    .how-it-works-inner {
      max-width: 1000px;
      margin: 0 auto;
    }

    .steps {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 40px;
      position: relative;
    }

    .steps::before {
      content: '';
      position: absolute;
      top: 48px;
      left: calc(16.67% + 20px);
      right: calc(16.67% + 20px);
      height: 2px;
      background: var(--border);
    }

    .step {
      text-align: center;
      position: relative;
    }

    .step-number {
      width: 96px;
      height: 96px;
      margin: 0 auto 24px;
      background: var(--white);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 32px;
      font-weight: 800;
      color: var(--primary);
      box-shadow: var(--shadow);
      position: relative;
      z-index: 1;
    }

    .step h3 {
      font-size: 18px;
      font-weight: 700;
      color: var(--primary);
      margin-bottom: 8px;
    }

    .step p {
      font-size: 15px;
      color: var(--text-muted);
      line-height: 1.5;
    }

    /* Testimonials */
    .testimonials {
      padding: 80px 24px;
      max-width: 1200px;
      margin: 0 auto;
    }

    .testimonials-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
      gap: 24px;
    }

    .testimonial-card {
      background: var(--light-gray);
      border-radius: var(--radius);
      padding: 32px;
    }

    .testimonial-text {
      font-size: 16px;
      line-height: 1.6;
      margin-bottom: 20px;
      color: var(--text-dark);
    }

    .testimonial-author {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .testimonial-avatar {
      width: 48px;
      height: 48px;
      border-radius: 50%;
      background: var(--primary);
      color: var(--white);
      display: flex;
      align-items: center;
      justify-content: center;
      font-weight: 700;
      font-size: 18px;
    }

    .testimonial-info strong {
      display: block;
      font-weight: 600;
    }

    .testimonial-info span {
      font-size: 13px;
      color: var(--text-muted);
    }

    /* Mobile App Promo */
    .mobile-app-promo {
      background: var(--primary);
      padding: 80px 24px;
      color: var(--white);
    }

    .mobile-app-inner {
      max-width: 1000px;
      margin: 0 auto;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 60px;
      align-items: center;
    }

    .mobile-app-content h2 {
      font-size: 36px;
      font-weight: 800;
      margin-bottom: 16px;
    }

    .mobile-app-content p {
      font-size: 16px;
      opacity: 0.85;
      margin-bottom: 32px;
    }

    .app-features {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 12px;
      margin-bottom: 32px;
    }

    .app-features li {
      display: flex;
      align-items: center;
      gap: 12px;
      font-size: 15px;
    }

    .app-features li svg {
      color: var(--accent);
      flex-shrink: 0;
    }

    .app-buttons {
      display: flex;
      gap: 16px;
      flex-wrap: wrap;
    }

    .app-btn {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      background: var(--white);
      color: var(--primary);
      padding: 12px 20px;
      border-radius: var(--radius-sm);
      font-weight: 600;
      font-size: 14px;
      transition: all 0.2s;
    }

    .app-btn:hover {
      transform: translateY(-2px);
      box-shadow: 0 4px 16px rgba(0,0,0,0.2);
    }

    .app-btn svg {
      width: 24px;
      height: 24px;
    }

    .mobile-app-visual {
      text-align: center;
    }

    .phone-mockup {
      width: 240px;
      height: 400px;
      background: var(--white);
      border-radius: 32px;
      margin: 0 auto;
      box-shadow: 0 20px 60px rgba(0,0,0,0.3);
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--primary);
      font-size: 80px;
    }

    /* Footer */
    .footer {
      background: #0d0b2e;
      color: var(--white);
      padding: 60px 24px 30px;
    }

    .footer-inner {
      max-width: 1200px;
      margin: 0 auto;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: 2fr repeat(3, 1fr);
      gap: 48px;
      margin-bottom: 48px;
    }

    .footer-brand p {
      font-size: 14px;
      opacity: 0.7;
      margin-top: 12px;
      max-width: 280px;
    }

    .footer-col h4 {
      font-size: 13px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.5px;
      margin-bottom: 16px;
      opacity: 0.5;
    }

    .footer-col ul {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 10px;
    }

    .footer-col a {
      font-size: 14px;
      opacity: 0.8;
      transition: opacity 0.2s;
    }

    .footer-col a:hover {
      opacity: 1;
    }

    .footer-bottom {
      border-top: 1px solid rgba(255,255,255,0.1);
      padding-top: 24px;
      display: flex;
      justify-content: space-between;
      align-items: center;
      font-size: 13px;
      opacity: 0.6;
    }

    /* Responsive */
    @media (max-width: 768px) {
      .nav-desktop {
        display: none;
      }

      .hamburger {
        display: flex;
      }

      .mobile-menu,
      .mobile-menu-overlay {
        display: block;
      }

      .hero {
        padding: 120px 20px 60px;
      }

      .search-bar {
        flex-direction: column;
        padding: 12px;
      }

      .search-field {
        width: 100%;
      }

      .search-btn {
        width: 100%;
        justify-content: center;
      }

      .stats-inner {
        grid-template-columns: repeat(2, 1fr);
        gap: 24px;
      }

      .stat-value {
        font-size: 28px;
      }

      .steps {
        grid-template-columns: 1fr;
        gap: 32px;
      }

      .steps::before {
        display: none;
      }

      .mobile-app-inner {
        grid-template-columns: 1fr;
        text-align: center;
      }

      .mobile-app-visual {
        order: -1;
      }

      .app-buttons {
        justify-content: center;
      }

      .footer-grid {
        grid-template-columns: repeat(2, 1fr);
      }

      .footer-brand {
        grid-column: span 2;
      }

      .footer-bottom {
        flex-direction: column;
        gap: 12px;
        text-align: center;
      }
    }

    @media (max-width: 480px) {
      .specialties-grid {
        grid-template-columns: repeat(2, 1fr);
      }

      .stats-inner {
        grid-template-columns: 1fr 1fr;
      }

      .footer-grid {
        grid-template-columns: 1fr;
      }

      .footer-brand {
        grid-column: 1;
      }
    }
  </style>
</head>
