  <script>
    // Mobile Menu Toggle
    const hamburger = document.getElementById('hamburger');
    const mobileMenu = document.getElementById('mobileMenu');
    const mobileOverlay = document.getElementById('mobileOverlay');
    const mobileClose = document.getElementById('mobileClose');

    function openMobileMenu() {
      mobileMenu.classList.add('active');
      mobileOverlay.classList.add('active');
      document.body.style.overflow = 'hidden';
    }

    function closeMobileMenu() {
      mobileMenu.classList.remove('active');
      mobileOverlay.classList.remove('active');
      document.body.style.overflow = '';
    }

    hamburger.addEventListener('click', openMobileMenu);
    mobileClose.addEventListener('click', closeMobileMenu);
    mobileOverlay.addEventListener('click', closeMobileMenu);

    // Autocomplete
    const searchInput = document.getElementById('searchInput');
    const autocomplete = document.getElementById('autocomplete');

    const suggestions = [
      { type: 'specialty', name: 'Primary Care', detail: 'Annual checkups, sick visits' },
      { type: 'specialty', name: 'Dentist', detail: 'Cleanings, fillings, oral health' },
      { type: 'specialty', name: 'Dermatologist', detail: 'Skin conditions, acne' },
      { type: 'specialty', name: 'Psychiatrist', detail: 'Mental health, medication' },
      { type: 'specialty', name: 'Eye Doctor', detail: 'Vision exams, glasses' },
      { type: 'specialty', name: 'Orthopedic Surgeon', detail: 'Joint pain, fractures' },
      { type: 'condition', name: 'Back Pain', detail: 'Lower back, upper back' },
      { type: 'condition', name: 'Headache', detail: 'Migraine, tension headache' },
      { type: 'condition', name: 'Anxiety', detail: 'Generalized anxiety disorder' },
      { type: 'condition', name: 'Cold and Flu', detail: 'Respiratory infections' }
    ];

    searchInput.addEventListener('input', function() {
      const query = this.value.toLowerCase().trim();
      if (query.length < 2) {
        autocomplete.classList.remove('active');
        return;
      }

      const filtered = suggestions.filter(s =>
        s.name.toLowerCase().includes(query) ||
        s.detail.toLowerCase().includes(query)
      ).slice(0, 6);

      if (filtered.length === 0) {
        autocomplete.classList.remove('active');
        return;
      }

      autocomplete.innerHTML = filtered.map(s => `
        <div class="autocomplete-item" data-value="${s.name}">
          <div class="autocomplete-item-icon">${s.type === 'specialty' ? '🏥' : '💊'}</div>
          <div class="autocomplete-item-text">
            <strong>${s.name}</strong>
            <span>${s.detail}</span>
          </div>
        </div>
      `).join('');

      autocomplete.classList.add('active');
    });

    autocomplete.addEventListener('click', function(e) {
      const item = e.target.closest('.autocomplete-item');
      if (item) {
        searchInput.value = item.dataset.value;
        autocomplete.classList.remove('active');
      }
    });

    document.addEventListener('click', function(e) {
      if (!e.target.closest('.search-field')) {
        autocomplete.classList.remove('active');
      }
    });

    // Search Form
    document.getElementById('searchForm').addEventListener('submit', function(e) {
      e.preventDefault();
      const query = searchInput.value;
      if (query) {
        alert(`Searching for "${query}"...\n\n(In a production environment, this would navigate to search results.)`);
      }
    });

    // Specialty Cards
    document.querySelectorAll('.specialty-card').forEach(card => {
      card.addEventListener('click', function() {
        const specialty = this.dataset.specialty;
        alert(`Browsing ${specialty.replace('-', ' ')}...\n\n(In a production environment, this would navigate to filtered search results.)`);
      });
    });

    // Smooth scroll for anchor links
    document.querySelectorAll('a[href^="#"]').forEach(anchor => {
      anchor.addEventListener('click', function(e) {
        const target = document.querySelector(this.getAttribute('href'));
        if (target) {
          e.preventDefault();
          target.scrollIntoView({ behavior: 'smooth' });
        }
      });
    });
  </script>
